/**
 * C-03 Input Mapper (P2 keyboard subset): arrows/WASD move, Z jump (A),
 * X action (B), Enter start. Produces the normalized InputCommand with a
 * per-seat monotonic seq (input-commands.md).
 */

import type { AxisValue, InputCommand } from "@dhaul/protocol";

const KEY_LEFT = new Set(["ArrowLeft", "KeyA"]);
const KEY_RIGHT = new Set(["ArrowRight", "KeyD"]);
const KEY_UP = new Set(["ArrowUp", "KeyW"]);
const KEY_DOWN = new Set(["ArrowDown", "KeyS"]);
const KEY_JUMP = new Set(["KeyZ", "Space"]);
const KEY_ACTION = new Set(["KeyX"]);
const KEY_START = new Set(["Enter"]);

export class KeyboardInputMapper {
  private readonly down = new Set<string>();
  private seq = 0;

  private readonly onKeyDown = (e: KeyboardEvent): void => {
    this.down.add(e.code);
  };
  private readonly onKeyUp = (e: KeyboardEvent): void => {
    this.down.delete(e.code);
  };

  attach(target: Window): void {
    target.addEventListener("keydown", this.onKeyDown);
    target.addEventListener("keyup", this.onKeyUp);
    target.addEventListener("blur", () => this.down.clear());
  }

  /** Reset seq coordination on (re)welcome (DESIGN §3.2). */
  resetSeq(): void {
    this.seq = 0;
  }

  private axis(neg: Set<string>, pos: Set<string>): AxisValue {
    const n = [...neg].some((k) => this.down.has(k));
    const p = [...pos].some((k) => this.down.has(k));
    if (n === p) return 0;
    return p ? 1 : -1;
  }

  private has(keys: Set<string>): boolean {
    return [...keys].some((k) => this.down.has(k));
  }

  /** Sample current levels into a command (call once per send tick). */
  sample(): InputCommand {
    return {
      seq: ++this.seq,
      axes: {
        x: this.axis(KEY_LEFT, KEY_RIGHT),
        y: this.axis(KEY_UP, KEY_DOWN),
      },
      jump: this.has(KEY_JUMP),
      action: this.has(KEY_ACTION),
      start: this.has(KEY_START),
    };
  }
}
===== net/prediction.ts =====
/**
 * C-04 local prediction + reconciliation (netcode-client DESIGN §8).
 * Pure module (no Phaser/DOM) so it unit-tests in Node.
 *
 * Predicts the LOCAL hauler only: x movement + jump against the level's
 * solid grid, using the same kinematics step as the server. On every
 * snapshot, drops acked inputs (`lastProcessedInputSeq`), rebases the body
 * from server truth and replays the remaining pending inputs.
 */

import type { HaulerPublic, InputCommand, WorldSnapshot } from "@dhaul/protocol";
import {
  createBody,
  stepHauler,
  type HaulerBody,
  type KinematicsConfig,
  type MoveInput,
  type SolidGrid,
} from "./kinematics.js";

const MAX_PENDING = 128; // ~4s at 30 Hz (DESIGN §8.2)

export class LocalPredictor {
  private readonly pending: InputCommand[] = [];
  private body: HaulerBody;
  /** Jump level of the last server-acked command (for replay edge detect). */
  private lastAckedJump = false;

  constructor(
    private readonly grid: SolidGrid,
    private readonly cfg: KinematicsConfig,
    readonly seatId: number,
  ) {
    this.body = createBody(0, 0);
  }

  /** Record + apply one sent command (call once per send tick). */
  predict(cmd: InputCommand): void {
    this.pending.push(cmd);
    if (this.pending.length > MAX_PENDING) this.pending.shift();
    stepHauler(this.body, toMove(cmd), this.grid, this.cfg);
  }

  /**
   * Reconcile against an authoritative snapshot (DESIGN §8.4):
   * drop acked inputs, rebase from server hauler, replay the rest.
   */
  reconcile(snapshot: WorldSnapshot): void {
    const me = snapshot.haulers.find((h) => h.seatId === this.seatId);
    if (!me) return;
    const ack = snapshot.lastProcessedInputSeq[this.seatId] ?? 0;
    while (this.pending.length > 0 && this.pending[0]!.seq <= ack) {
      this.lastAckedJump = this.pending.shift()!.jump;
    }
    this.body = rebase(me, this.lastAckedJump);
    for (const cmd of this.pending) {
      stepHauler(this.body, toMove(cmd), this.grid, this.cfg);
    }
  }

  /** Displayed local transform (post-predict). */
  get state(): Readonly<HaulerBody> {
    return this.body;
  }

  get pendingCount(): number {
    return this.pending.length;
  }
}

function toMove(cmd: InputCommand): MoveInput {
  return { moveX: cmd.axes.x, jump: cmd.jump };
}

/** Server truth for position/velocity; edge-detect resumes from acked jump level. */
function rebase(server: HaulerPublic, jumpHeld: boolean): HaulerBody {
  return {
    x: server.x,
    y: server.y,
    vx: server.vx,
    vy: server.vy,
    facing: server.facing,
    grounded: server.anim !== "jump" && server.anim !== "falling",
    jumpHeld,
    jumpBuffer: 0,
  };
}
===== net/interpolation.ts =====
/**
 * C-04 remote hauler interpolation (netcode-client DESIGN §9).
 * Pure module: buffers timed snapshots per seat, samples ~2 ticks in the
 * past to absorb jitter, holds the last transform on underrun (no long
 * extrapolation).
 */

import type { HaulerPublic, WorldSnapshot } from "@dhaul/protocol";

export interface RemoteSample {
  x: number;
  y: number;
  facing: 1 | -1;
  anim: string;
  control: string;
  name?: string;
}

interface TimedHauler {
  atMs: number;
  hauler: HaulerPublic;
}

const BUFFER_MAX = 12;

export class RemoteInterpolator {
  private readonly buffers = new Map<number, TimedHauler[]>();

  constructor(
    /** Render delay in ms (~2 ticks at 30 Hz). */
    private readonly delayMs = 66,
  ) {}

  /** Ingest an authoritative snapshot (client receive time). */
  push(snapshot: WorldSnapshot, nowMs: number, excludeSeatId?: number): void {
    for (const hauler of snapshot.haulers) {
      if (hauler.seatId === excludeSeatId) continue;
      let buf = this.buffers.get(hauler.seatId);
      if (!buf) {
        buf = [];
        this.buffers.set(hauler.seatId, buf);
      }
      buf.push({ atMs: nowMs, hauler });
      while (buf.length > BUFFER_MAX) buf.shift();
    }
  }

  /** Sample a seat's transform at `nowMs - delayMs`. Null if never seen. */
  sample(seatId: number, nowMs: number): RemoteSample | null {
    const buf = this.buffers.get(seatId);
    if (!buf || buf.length === 0) return null;
    const t = nowMs - this.delayMs;

    // Find the segment [a, b] spanning t.
    let a = buf[0]!;
    let b = buf[buf.length - 1]!;
    for (let i = 0; i < buf.length - 1; i++) {
      if (buf[i]!.atMs <= t && buf[i + 1]!.atMs >= t) {
        a = buf[i]!;
        b = buf[i + 1]!;
        break;
      }
    }
    if (t <= a.atMs) return toSample(a.hauler);
    if (t >= b.atMs) return toSample(b.hauler); // underrun: hold last
    const alpha = (t - a.atMs) / (b.atMs - a.atMs);
    const near = alpha < 0.5 ? a.hauler : b.hauler;
    const sample = toSample(near);
    sample.x = a.hauler.x + (b.hauler.x - a.hauler.x) * alpha;
    sample.y = a.hauler.y + (b.hauler.y - a.hauler.y) * alpha;
    return sample;
  }
}

function toSample(h: HaulerPublic): RemoteSample {
  const s: RemoteSample = {
    x: h.x,
    y: h.y,
    facing: h.facing,
    anim: h.anim,
    control: h.control,
  };
  if (h.name !== undefined) s.name = h.name;
  return s;
}
===== net/kinematics.ts =====
/**
 * Pure hauler movement kinematics — P2 subset (run / jump / air-steer /
 * gravity / AABB vs solid grid). No treasure, traps, encumbrance, or
 * surface-friction variants yet.
 *
 * VERBATIM COPY of server/src/sim/kinematics.ts (prediction parity, per
 * netcode-client DESIGN §8.1 / §16 — extraction into a shared package is a
 * P3+ cleanup). Edit the server file first, then re-copy. Dependency-free.
 *
 * Coordinates: world pixels, y-down (docs/interfaces/level-format.md).
 * Fixed timestep only — dt comes from config, never wall clock.
 */

/** All tunable movement constants live here (simulation DESIGN §5.2). */
export interface KinematicsConfig {
  /** Fixed physics timestep in seconds (1 / tickRate). */
  dt: number;
  /** Hauler AABB half extents in px. */
  halfW: number;
  halfH: number;
  /** Ground run acceleration px/s². */
  runAccel: number;
  /** Airborne steer acceleration px/s² (reduced vs ground). */
  airAccel: number;
  /** Ground deceleration toward 0 when no input, px/s². */
  groundFriction: number;
  /** Max horizontal speed px/s. */
  maxSpeed: number;
  /** Gravity px/s² (positive = down). */
  gravity: number;
  /** Terminal fall speed px/s. */
  maxFallSpeed: number;
  /** Upward jump impulse magnitude px/s. */
  jumpSpeed: number;
  /** Jump input buffered for this many steps while airborne. */
  jumpBufferSteps: number;
}

export const DEFAULT_KINEMATICS: KinematicsConfig = {
  dt: 1 / 30,
  halfW: 12,
  halfH: 14,
  runAccel: 1400,
  airAccel: 700,
  groundFriction: 1800,
  maxSpeed: 160,
  gravity: 1500,
  maxFallSpeed: 540,
  jumpSpeed: 430,
  jumpBufferSteps: 3,
};

/** Mutable hauler body state advanced by {@link stepHauler}. */
export interface HaulerBody {
  x: number;
  y: number;
  vx: number;
  vy: number;
  grounded: boolean;
  facing: 1 | -1;
  /** Previous step's jump level, for edge detection. */
  jumpHeld: boolean;
  /** Remaining buffered-jump steps (0 = none pending). */
  jumpBuffer: number;
}

export function createBody(x: number, y: number): HaulerBody {
  return {
    x,
    y,
    vx: 0,
    vy: 0,
    grounded: false,
    facing: 1,
    jumpHeld: false,
    jumpBuffer: 0,
  };
}

/** Movement-relevant slice of an InputCommand (levels, not edges). */
export interface MoveInput {
  moveX: -1 | 0 | 1;
  jump: boolean;
}

export const NEUTRAL_INPUT: MoveInput = { moveX: 0, jump: false };

/** Solid-cell query the physics needs; out-of-bounds must read as solid. */
export interface SolidGrid {
  blockSizePx: number;
  widthCells: number;
  heightCells: number;
  isSolid(cx: number, cy: number): boolean;
}

const EPS = 0.001;

function overlapsSolid(
  grid: SolidGrid,
  x: number,
  y: number,
  cfg: KinematicsConfig,
): boolean {
  const bs = grid.blockSizePx;
  const x0 = Math.floor((x - cfg.halfW) / bs);
  const x1 = Math.floor((x + cfg.halfW - EPS) / bs);
  const y0 = Math.floor((y - cfg.halfH) / bs);
  const y1 = Math.floor((y + cfg.halfH - EPS) / bs);
  for (let cy = y0; cy <= y1; cy++) {
    for (let cx = x0; cx <= x1; cx++) {
      if (
        cx < 0 ||
        cy < 0 ||
        cx >= grid.widthCells ||
        cy >= grid.heightCells ||
        grid.isSolid(cx, cy)
      ) {
        return true;
      }
    }
  }
  return false;
}

/**
 * Axis-separated, sub-stepped move. Sub-steps never exceed half a block so a
 * body cannot tunnel through a one-cell wall/floor at any legal speed.
 * On hit, snaps flush to the colliding cell face and zeroes the axis velocity.
 * Returns true if the axis collided.
 */
function moveAxis(
  body: HaulerBody,
  grid: SolidGrid,
  cfg: KinematicsConfig,
  axis: "x" | "y",
  delta: number,
): boolean {
  if (delta === 0) return false;
  const bs = grid.blockSizePx;
  const maxStep = bs / 2;
  const sign = Math.sign(delta);
  let remaining = Math.abs(delta);
  while (remaining > 0) {
    const step = Math.min(remaining, maxStep);
    remaining -= step;
    body[axis] += step * sign;
    if (overlapsSolid(grid, body.x, body.y, cfg)) {
      if (axis === "x") {
        if (sign > 0) {
          const col = Math.floor((body.x + cfg.halfW - EPS) / bs);
          body.x = col * bs - cfg.halfW - EPS;
        } else {
          const col = Math.floor((body.x - cfg.halfW) / bs);
          body.x = (col + 1) * bs + cfg.halfW + EPS;
        }
        body.vx = 0;
      } else {
        if (sign > 0) {
          const row = Math.floor((body.y + cfg.halfH - EPS) / bs);
          body.y = row * bs - cfg.halfH - EPS;
        } else {
          const row = Math.floor((body.y - cfg.halfH) / bs);
          body.y = (row + 1) * bs + cfg.halfH + EPS;
        }
        body.vy = 0;
      }
      return true;
    }
  }
  return false;
}

function moveToward(value: number, target: number, maxDelta: number): number {
  if (value < target) return Math.min(value + maxDelta, target);
  return Math.max(value - maxDelta, target);
}

/**
 * Advance one fixed step. Deterministic given (body, input, grid, cfg).
 * Jump uses edge detection (`input.jump` transition false→true) with a short
 * buffer so presses just before landing still fire (input-commands.md:
 * "Jump edge triggers once per press cycle").
 */
export function stepHauler(
  body: HaulerBody,
  input: MoveInput,
  grid: SolidGrid,
  cfg: KinematicsConfig,
): void {
  // Jump edge → buffer.
  if (input.jump && !body.jumpHeld) {
    body.jumpBuffer = cfg.jumpBufferSteps;
  }
  body.jumpHeld = input.jump;

  // Horizontal accel / friction.
  if (input.moveX !== 0) {
    const accel = body.grounded ? cfg.runAccel : cfg.airAccel;
    body.vx = moveToward(body.vx, input.moveX * cfg.maxSpeed, accel * cfg.dt);
    body.facing = input.moveX;
  } else if (body.grounded) {
    body.vx = moveToward(body.vx, 0, cfg.groundFriction * cfg.dt);
  }

  // Jump consume + gravity.
  if (body.grounded && body.jumpBuffer > 0) {
    body.vy = -cfg.jumpSpeed;
    body.grounded = false;
    body.jumpBuffer = 0;
  } else if (body.jumpBuffer > 0) {
    body.jumpBuffer -= 1;
  }
  body.vy = Math.min(body.vy + cfg.gravity * cfg.dt, cfg.maxFallSpeed);

  // Integrate with collision.
  moveAxis(body, grid, cfg, "x", body.vx * cfg.dt);
  const hitY = moveAxis(body, grid, cfg, "y", body.vy * cfg.dt);
  // Landed if the vertical move hit while descending; otherwise airborne
  // (gravity guarantees vy > 0 on any tick that did not end on a floor).
  body.grounded = hitY && body.vy === 0 && overlapsSolid(grid, body.x, body.y + 1, cfg);
}

