/**
 * C-04 room transport — thin wrapper over colyseus.js for the P2 slice.
 *
 * Handshake travels as join options (see @dhaul/protocol codec JoinOptions);
 * every server message arrives on a channel named by its wire `type`. State
 * sync is plain JSON `snapshot` broadcasts (no Colyseus schema), matching the
 * room's transport adaptation.
 */

import { Client, type Room } from "colyseus.js";
import {
  protocolVersion,
  type C2S_Input,
  type GameEvent,
  type InputCommand,
  type S2C_Error,
  type S2C_SeatUpdate,
  type S2C_Snapshot,
  type S2C_Welcome,
} from "@dhaul/protocol";

export interface RoomConnectArgs {
  wsUrl: string;
  sessionId: string;
  seatToken: string;
  reconnectToken?: string;
}

export interface RoomHandlers {
  onWelcome(msg: S2C_Welcome): void;
  onSnapshot(msg: S2C_Snapshot): void;
  onSeatUpdate(msg: S2C_SeatUpdate): void;
  onEvent(event: GameEvent): void;
  onServerError(msg: S2C_Error): void;
  /** Connection dropped (code from Colyseus; consented leaves included). */
  onLeave(code: number): void;
}

export class RoomConnection {
  private constructor(private readonly room: Room) {}

  /**
   * Join the session's room by id (roomId === contract sessionId). Rejects
   * with the Colyseus error (`.code` is a COLYSEUS_ERROR_CODES numeric) if the
   * server refuses the handshake (protocol/auth/full).
   */
  static async connect(args: RoomConnectArgs, handlers: RoomHandlers): Promise<RoomConnection> {
    const client = new Client(args.wsUrl);
    const options: Record<string, unknown> = {
      protocolVersion,
      sessionId: args.sessionId,
      seatToken: args.seatToken,
    };
    if (args.reconnectToken !== undefined) options["reconnectToken"] = args.reconnectToken;

    const room = await client.joinById(args.sessionId, options);
    room.onMessage("welcome", (m) => handlers.onWelcome(m as S2C_Welcome));
    room.onMessage("snapshot", (m) => handlers.onSnapshot(m as S2C_Snapshot));
    room.onMessage("seat_update", (m) => handlers.onSeatUpdate(m as S2C_SeatUpdate));
    room.onMessage("event", (m) => handlers.onEvent((m as { event: GameEvent }).event));
    room.onMessage("error", (m) => handlers.onServerError(m as S2C_Error));
    room.onMessage("pong", () => undefined);
    // Forward-compatibility: ignore channels this build doesn't handle.
    room.onMessage("*", () => undefined);
    room.onLeave((code) => handlers.onLeave(code));
    room.onError((_code, message) => console.error("[room] error", message));
    return new RoomConnection(room);
  }

  /** Send one input command for this seat (server validates seat ownership). */
  sendInput(seatId: number, command: InputCommand): void {
    const msg: C2S_Input = { type: "input", seatId, command };
    this.room.send("input", msg);
  }

  ping(): void {
    this.room.send("ping", { type: "ping", clientTime: Date.now() });
  }

  leave(): void {
    void this.room.send("leave", { type: "leave" });
    void this.room.leave(true);
  }
}

