input.content:
/**
 * C-01/C-02 P2 game scene: join the HaulSession room and render the movement
 * slice on the box level. Placeholder rects only (real sprites land with the
 * art pass). Wires the pure net modules:
 *   - KeyboardInputMapper  → sample one InputCommand per 30 Hz send tick
 *   - LocalPredictor       → predict + reconcile the local hauler
 *   - RemoteInterpolator   → smooth remote haulers ~2 ticks behind
 * Server is authoritative; the client predicts local movement only.
 */

import Phaser from "phaser";
import type {
  S2C_Error,
  S2C_SeatUpdate,
  S2C_Snapshot,
  S2C_Welcome,
  SeatPublic,
} from "@dhaul/protocol";
import { fetchLevel, gridFromGeometry, type LevelGeometry } from "../net/lobbyClient.js";
import { KeyboardInputMapper } from "../net/inputMapper.js";
import { LocalPredictor } from "../net/prediction.js";
import { RemoteInterpolator } from "../net/interpolation.js";
import { DEFAULT_KINEMATICS, type SolidGrid } from "../net/kinematics.js";
import { RoomConnection } from "../net/roomClient.js";
import { saveBundle, clearBundle, type SessionBundle } from "../net/tokenStore.js";

const SEAT_COLORS = [0xff8c42, 0x4aa3ff, 0xff6fb5, 0x8ce38c] as const;
const SEND_INTERVAL_MS = 1000 / 30;

export interface GameSceneData {
  serverUrl: string;
  wsUrl: string;
  sessionId: string;
  seatToken: string;
  reconnectToken: string;
  displayName: string;
}

type ConnState = "connecting" | "playing" | "reconnecting" | "lost";

export class GameScene extends Phaser.Scene {
  private data!: GameSceneData;
  private geo!: LevelGeometry;
  private grid!: SolidGrid;

  private room?: RoomConnection;
  private readonly mapper = new KeyboardInputMapper();
  private predictor?: LocalPredictor;
  private readonly interp = new RemoteInterpolator();

  private seatId = -1;
  private seats: SeatPublic[] = [];
  private connState: ConnState = "connecting";
  private lastTick = 0;
  private sendAccumMs = 0;

  private levelGfx!: Phaser.GameObjects.Graphics;
  private haulerGfx!: Phaser.GameObjects.Graphics;
  private nameTexts: Phaser.GameObjects.Text[] = [];
  private hud!: Phaser.GameObjects.Text;
  private worldOffsetX = 0;
  private worldOffsetY = 0;

  constructor() {
    super("Game");
  }

  init(data: GameSceneData): void {
    this.data = data;
  }

  async create(): Promise<void> {
    this.levelGfx = this.add.graphics();
    this.haulerGfx = this.add.graphics();
    this.hud = this.add
      .text(10, 8, "", { fontFamily: "monospace", fontSize: "13px", color: "#d7cff0" })
      .setScrollFactor(0)
      .setDepth(100);

    try {
      this.geo = await fetchLevel(this.data.serverUrl, "box_level");
    } catch {
      this.setConnState("lost");
      this.hud.setText("failed to load level geometry");
      return;
    }
    this.grid = gridFromGeometry(this.geo) as SolidGrid;
    this.centerLevel();
    this.drawLevel();

    this.mapper.attach(window);
    await this.connect();

    // 30 Hz input send loop is driven from update() via an accumulator so the
    // predict/send cadence matches the server tick regardless of frame rate.
    this.events.on(Phaser.Scenes.Events.SHUTDOWN, () => this.room?.leave());
  }

  private async connect(): Promise<void> {
    this.setConnState(this.connState === "lost" ? "reconnecting" : "connecting");
    try {
      this.room = await RoomConnection.connect(
        {
          wsUrl: this.data.wsUrl,
          sessionId: this.data.sessionId,
          seatToken: this.data.seatToken,
          reconnectToken: this.data.reconnectToken,
        },
        {
          onWelcome: (m) => this.onWelcome(m),
          onSnapshot: (m) => this.onSnapshot(m),
          onSeatUpdate: (m) => this.onSeatUpdate(m),
          onEvent: () => undefined,
          onServerError: (m) => this.onServerError(m),
          onLeave: (code) => this.onLeave(code),
        },
      );
    } catch (err) {
      // Auth failure on a stored bundle = grace expired → back to lobby.
      clearBundle();
      this.setConnState("lost");
      this.hud.setText(`join rejected: ${errText(err)} — refresh to re-enter`);
    }
  }

  private onWelcome(m: S2C_Welcome): void {
    this.seatId = m.seatId;
    this.mapper.resetSeq();
    this.predictor = new LocalPredictor(this.grid, DEFAULT_KINEMATICS, m.seatId);
    this.predictor.reconcile(m.snapshot);
    this.interp.push(m.snapshot, performance.now(), m.seatId);
    this.seats = m.snapshot.haulers.map((h) => haulerToSeat(h));
    this.data.reconnectToken = m.reconnectToken;
    this.persistBundle();
    this.setConnState("playing");
  }

  private onSnapshot(m: S2C_Snapshot): void {
    this.lastTick = m.snapshot.tick;
    this.predictor?.reconcile(m.snapshot);
    this.interp.push(m.snapshot, performance.now(), this.seatId);
    if (this.connState !== "playing") this.setConnState("playing");
  }

  private onSeatUpdate(m: S2C_SeatUpdate): void {
    this.seats = m.seats;
  }

  private onServerError(m: S2C_Error): void {
    console.warn("[server error]", m.code, m.message);
  }

  private onLeave(code: number): void {
    this.room = undefined;
    // 1000 = normal / consented; anything else during play = try to reconnect.
    if (this.connState === "playing" && code !== 1000) {
      this.setConnState("reconnecting");
      this.time.delayedCall(500, () => void this.connect());
    } else if (this.connState !== "lost") {
      this.setConnState("lost");
    }
  }

  override update(_time: number, deltaMs: number): void {
    // Fixed-rate input send + local prediction (one predict per command).
    if (this.room && this.predictor && this.connState === "playing") {
      this.sendAccumMs += deltaMs;
      while (this.sendAccumMs >= SEND_INTERVAL_MS) {
        this.sendAccumMs -= SEND_INTERVAL_MS;
        const cmd = this.mapper.sample();
        this.predictor.predict(cmd);
        this.room.sendInput(this.seatId, cmd);
      }
    }
    this.render();
  }

  private render(): void {
    const g = this.haulerGfx;
    g.clear();
    this.ensureNameTexts();
    const now = performance.now();
    const { halfW, halfH } = DEFAULT_KINEMATICS;

    for (let seat = 0; seat < 4; seat++) {
      let x: number | null = null;
      let y: number | null = null;
      let facing: 1 | -1 = 1;
      let present = false;

      if (seat === this.seatId && this.predictor) {
        const b = this.predictor.state;
        x = b.x;
        y = b.y;
        facing = b.facing;
        present = true;
      } else {
        const s = this.interp.sample(seat, now);
        if (s) {
          x = s.x;
          y = s.y;
          facing = s.facing;
          present = true;
        }
      }

      const label = this.nameTexts[seat]!;
      if (!present || x === null || y === null) {
        label.setVisible(false);
        continue;
      }
      const wx = this.worldOffsetX + x;
      const wy = this.worldOffsetY + y;
      const color = SEAT_COLORS[seat]!;
      g.fillStyle(color, seat === this.seatId ? 1 : 0.82);
      g.fillRect(wx - halfW, wy - halfH, halfW * 2, halfH * 2);
      // Facing pip.
      g.fillStyle(0xffffff, 0.9);
      g.fillRect(wx + facing * (halfW - 4) - 2, wy - halfH + 3, 4, 4);

      const seatInfo = this.seats.find((s) => s.seatId === seat);
      const name = seatInfo?.displayName ?? (seatInfo?.control === "ai" ? "AI" : `P${seat + 1}`);
      label
        .setText(seat === this.seatId ? `${name} (you)` : name)
        .setPosition(wx, wy - halfH - 14)
        .setVisible(true);
    }

    this.hud.setText(this.hudText());
  }

  private hudText(): string {
    const conn = this.connState.toUpperCase();
    const seat = this.seatId >= 0 ? `seat ${this.seatId}` : "—";
    const pending = this.predictor?.pendingCount ?? 0;
    const code = this.data.sessionId.slice(0, 8);
    return `${conn}  ${seat}  tick ${this.lastTick}  pending ${pending}  room ${code}`;
  }

  private ensureNameTexts(): void {
    if (this.nameTexts.length > 0) return;
    for (let i = 0; i < 4; i++) {
      this.nameTexts.push(
        this.add
          .text(0, 0, "", { fontFamily: "monospace", fontSize: "11px", color: "#ffffff" })
          .setOrigin(0.5, 1)
          .setDepth(50),
      );
    }
  }

  private centerLevel(): void {
    const w = this.geo.width * this.geo.blockSizePx;
    const h = this.geo.height * this.geo.blockSizePx;
    this.worldOffsetX = Math.round((this.scale.width - w) / 2);
    this.worldOffsetY = Math.round((this.scale.height - h) / 2);
  }

  private drawLevel(): void {
    const g = this.levelGfx;
    const bs = this.geo.blockSizePx;
    g.clear();
    // Bounds frame.
    g.lineStyle(2, 0x3d3255, 1);
    g.strokeRect(
      this.worldOffsetX,
      this.worldOffsetY,
      this.geo.width * bs,
      this.geo.height * bs,
    );
    // Solid cells.
    g.fillStyle(0x4a4066, 1);
    for (let cy = 0; cy < this.geo.height; cy++) {
      const row = this.geo.solid[cy] ?? "";
      for (let cx = 0; cx < this.geo.width; cx++) {
        if (row[cx] === "#") {
          g.fillRect(this.worldOffsetX + cx * bs, this.worldOffsetY + cy * bs, bs, bs);
        }
      }
    }
    // Exit zone.
    const e = this.geo.exit;
    g.fillStyle(0x6be6a0, 0.28);
    g.fillRect(this.worldOffsetX + e.x, this.worldOffsetY + e.y, e.width, e.height);
  }

  private setConnState(s: ConnState): void {
    this.connState = s;
  }

  private persistBundle(): void {
    const bundle: SessionBundle = {
      serverUrl: this.data.serverUrl,
      wsUrl: this.data.wsUrl,
      sessionId: this.data.sessionId,
      seatId: this.seatId,
      seatToken: this.data.seatToken,
      reconnectToken: this.data.reconnectToken,
      displayName: this.data.displayName,
    };
    saveBundle(bundle);
  }
}

function haulerToSeat(h: { seatId: number; control: string; name?: string }): SeatPublic {
  const seat: SeatPublic = {
    seatId: h.seatId as SeatPublic["seatId"],
    occupied: true,
    control: h.control as SeatPublic["control"],
    ready: false,
  };
  if (h.name !== undefined) seat.displayName = h.name;
  return seat;
}

function errText(err: unknown): string {
  if (err && typeof err === "object" && "message" in err) {
    return String((err as { message: unknown }).message);
  }
  return "connection failed";
}

