/**
 * C-04 session orchestrator: owns the room connection, local prediction, and
 * remote interpolation for one seat, and drives the fixed 30 Hz input send
 * loop. The render scene (C-01/C-02) reads `latestSnapshot()` / `localState()`
 * / `interpolator()` and stays free of transport concerns.
 *
 * Server is authoritative; this predicts the LOCAL hauler's movement only.
 */

import type { S2C_Error, S2C_SeatUpdate, S2C_Snapshot, S2C_Welcome, WorldSnapshot } from "@dhaul/protocol";
import { KeyboardInputMapper } from "./inputMapper.js";
import { RemoteInterpolator } from "./interpolation.js";
import { DEFAULT_KINEMATICS, type HaulerBody, type SolidGrid } from "./kinematics.js";
import { gridFromGeometry, type LevelGeometry } from "./lobbyClient.js";
import { LocalPredictor } from "./prediction.js";
import { RoomConnection } from "./roomClient.js";
import { clearBundle, saveBundle, type SessionBundle } from "./tokenStore.js";

export type ConnectionState = "connecting" | "playing" | "reconnecting" | "lost";

export interface SessionArgs {
  serverUrl: string;
  wsUrl: string;
  sessionId: string;
  seatToken: string;
  reconnectToken: string;
  displayName: string;
  geometry: LevelGeometry;
}

const SEND_INTERVAL_MS = 1000 / 30;

export class SessionClient {
  seatId = -1;
  connectionState: ConnectionState = "connecting";

  private readonly grid: SolidGrid;
  private readonly mapper = new KeyboardInputMapper();
  private readonly interp = new RemoteInterpolator();
  private predictor?: LocalPredictor;
  private room?: RoomConnection;
  private snapshot?: WorldSnapshot;
  private reconnectToken: string;
  private sendTimer?: ReturnType<typeof setInterval>;
  private disposed = false;

  private constructor(private readonly args: SessionArgs) {
    this.grid = gridFromGeometry(args.geometry) as SolidGrid;
    this.reconnectToken = args.reconnectToken;
  }

  /**
   * Fetch geometry, then connect. Rejects if the initial join is refused
   * (protocol/auth/full) — caller clears any stored bundle and returns to the
   * lobby. Later drops are handled internally with a reconnect attempt.
   */
  static async start(args: SessionArgs): Promise<SessionClient> {
    const client = new SessionClient(args);
    client.mapper.attach(window);
    await client.connect();
    client.sendTimer = setInterval(() => client.sendTick(), SEND_INTERVAL_MS);
    return client;
  }

  latestSnapshot(): WorldSnapshot | undefined {
    return this.snapshot;
  }

  /** Predicted local body (post-reconcile), or undefined before welcome. */
  localState(): Readonly<HaulerBody> | undefined {
    return this.predictor?.state;
  }

  interpolator(): RemoteInterpolator {
    return this.interp;
  }

  dispose(): void {
    this.disposed = true;
    if (this.sendTimer) clearInterval(this.sendTimer);
    this.room?.leave();
    clearBundle();
  }

  private async connect(): Promise<void> {
    this.room = await RoomConnection.connect(
      {
        wsUrl: this.args.wsUrl,
        sessionId: this.args.sessionId,
        seatToken: this.args.seatToken,
        reconnectToken: this.reconnectToken,
      },
      {
        onWelcome: (m) => this.onWelcome(m),
        onSnapshot: (m) => this.onSnapshot(m),
        onSeatUpdate: (m) => this.onSeatUpdate(m),
        onEvent: () => undefined,
        onServerError: (m) => this.onServerError(m),
        onLeave: (code) => this.onLeave(code),
      },
    );
  }

  private onWelcome(m: S2C_Welcome): void {
    this.seatId = m.seatId;
    this.mapper.resetSeq();
    this.predictor = new LocalPredictor(this.grid, DEFAULT_KINEMATICS, m.seatId);
    this.predictor.reconcile(m.snapshot);
    this.snapshot = m.snapshot;
    this.interp.push(m.snapshot, performance.now(), m.seatId);
    this.reconnectToken = m.reconnectToken;
    this.persist();
    this.connectionState = "playing";
  }

  private onSnapshot(m: S2C_Snapshot): void {
    this.snapshot = m.snapshot;
    this.predictor?.reconcile(m.snapshot);
    this.interp.push(m.snapshot, performance.now(), this.seatId);
    if (this.connectionState !== "playing") this.connectionState = "playing";
  }

  private onSeatUpdate(_m: S2C_SeatUpdate): void {
    // Seat metadata (names/control) is also carried on each snapshot's haulers;
    // P2 render reads interpolation samples, so nothing extra to store here.
  }

  private onServerError(m: S2C_Error): void {
    console.warn("[server error]", m.code, m.message);
  }

  private onLeave(code: number): void {
    this.room = undefined;
    if (this.disposed) return;
    // 1000 = normal close; anything else mid-play → attempt reconnect within
    // the server's grace window using the rotated reconnect token.
    if (this.connectionState === "playing" && code !== 1000) {
      this.connectionState = "reconnecting";
      setTimeout(() => void this.reconnect(), 500);
    } else if (this.connectionState !== "lost") {
      this.connectionState = "lost";
    }
  }

  private async reconnect(): Promise<void> {
    if (this.disposed) return;
    try {
      await this.connect();
    } catch {
      // Grace expired / seat gone: give up and clear the stale bundle.
      clearBundle();
      this.connectionState = "lost";
    }
  }

  private sendTick(): void {
    if (this.connectionState !== "playing" || !this.room || !this.predictor) return;
    const cmd = this.mapper.sample();
    this.predictor.predict(cmd);
    this.room.sendInput(this.seatId, cmd);
  }

  private persist(): void {
    const bundle: SessionBundle = {
      serverUrl: this.args.serverUrl,
      wsUrl: this.args.wsUrl,
      sessionId: this.args.sessionId,
      seatId: this.seatId,
      seatToken: this.args.seatToken,
      reconnectToken: this.reconnectToken,
      displayName: this.args.displayName,
    };
    saveBundle(bundle);
  }
}

